import {communityRecipes, originalMedia} from './catalogue.js';
const originalRecipes = [
 {id:'chicken-bowl',title:'Chicken Rice Bowl',description:'Golden chicken, fluffy rice and a crisp, colourful salad. A simple bowl that makes lunch feel special.',image:0,prep:10,cook:20,kcal:520,protein:38,category:'High protein',equipment:['Stovetop'],ingredients:[['Chicken',150,'g'],['Rice',60,'g dry'],['Cucumber',75,'g'],['Tomato',80,'g'],['Lemon',0.25,''],['Olive oil',2,'tsp']],steps:[['Get the rice going','Rinse the rice. Add to a small saucepan with water according to the packet, bring to a boil, cover and cook on low until tender, about 15–18 minutes.'],['Prepare the salad','Dice the cucumber and tomato. Toss with the lemon juice, half the oil and a pinch of salt and pepper.'],['Cook the chicken','Slice the chicken into even strips and season. Heat the remaining oil in a frying pan over medium-high heat. Cook for 6–8 minutes, turning regularly, until the centre reaches 74°C.'],['Build your bowl','Rest the chicken for 3 minutes. Fluff the rice and spoon into a bowl, then add the chicken and fresh salad. Drizzle over the salad juices.']]},
 {id:'tomato-pasta',title:'Tomato Basil Pasta',description:'A bright, garlicky tomato sauce with fresh basil. Everyday ingredients, a very good dinner.',image:1,prep:5,cook:20,kcal:450,protein:15,category:'Vegetarian',equipment:['Stovetop'],ingredients:[['Pasta',90,'g dry'],['Tomato',200,'g'],['Garlic',2,'cloves'],['Basil',5,'g'],['Parmesan',15,'g'],['Olive oil',1,'tsp']],steps:[['Boil the pasta','Bring a saucepan of salted water to a boil. Cook the pasta according to its packet until al dente. Before draining, save a mug of the cooking water.'],['Start the sauce','Chop the tomatoes and finely slice the garlic. Warm the oil in a frying pan over medium heat. Add the garlic and stir for 30 seconds without browning.'],['Let it simmer','Add the tomatoes and a pinch of salt. Simmer for 10–12 minutes, stirring and crushing gently, until saucy. Add a little pasta water if it gets dry.'],['Toss and serve','Add the drained pasta, torn basil and grated Parmesan. Toss with a splash of pasta water until glossy. Use vegetarian hard cheese if needed.']]},
 {id:'fried-rice',title:'Vegetable Fried Rice',description:'A colourful, one-pan favourite for turning leftover rice and vegetables into something delicious.',image:2,prep:10,cook:10,kcal:430,protein:16,category:'Vegetarian',equipment:['Stovetop'],ingredients:[['Rice',150,'g cooked and chilled'],['Eggs',2,''],['Carrot',60,'g'],['Peas',50,'g'],['Garlic',1,'clove'],['Soy sauce',2,'tsp'],['Olive oil',1,'tsp']],steps:[['Prep everything first','Dice the carrot finely, mince the garlic and beat the eggs. Break up clumps of chilled rice with a fork. Use rice that was promptly chilled and refrigerated, not rice left at room temperature.'],['Soften the vegetables','Heat the oil in a large frying pan over medium-high heat. Add carrot and a splash of water. Stir-fry 3–4 minutes, then add peas and garlic for 1 minute.'],['Scramble the eggs','Push the vegetables to one side. Pour the eggs into the empty side and stir until fully set, about 1–2 minutes.'],['Fry the rice','Add rice and soy sauce. Stir-fry for 3–4 minutes, breaking up clumps, until steaming hot throughout. Serve immediately; reheat rice only once.']]},
 {id:'chickpea-salad',title:'Lemony Chickpea Salad',description:'Fresh, crunchy and ready in minutes. A satisfying lunch with no cooking required.',image:3,prep:15,cook:0,kcal:390,protein:16,category:'Vegetarian',equipment:[],ingredients:[['Chickpeas',150,'g canned, drained'],['Cucumber',100,'g'],['Tomato',100,'g'],['Feta',30,'g'],['Lemon',0.5,''],['Olive oil',1,'tsp']],steps:[['Rinse the chickpeas','Drain the canned chickpeas, rinse under cold running water and let drain well.'],['Chop the vegetables','Cut cucumber and tomatoes into bite-size pieces. Place in a large bowl with the chickpeas.'],['Mix the dressing','Whisk the lemon juice with olive oil and black pepper. Taste before adding salt because feta is already salty.'],['Finish the salad','Toss with the dressing and crumble feta on top. Use vegetarian feta if needed. Enjoy immediately or keep covered in the fridge for up to 2 days.']]},
 {id:'omelette',title:'Spinach & Mushroom Omelette',description:'Soft eggs folded around golden mushrooms and tender spinach. Your speedy breakfast-for-dinner.',image:4,prep:5,cook:10,kcal:310,protein:23,category:'Vegetarian',equipment:['Stovetop'],ingredients:[['Eggs',3,''],['Spinach',50,'g'],['Mushrooms',100,'g'],['Milk',1,'tbsp'],['Olive oil',1,'tsp']],steps:[['Prepare the filling','Slice the mushrooms and wash the spinach. Beat the eggs with the milk and a pinch of salt and pepper.'],['Cook the vegetables','Heat half the oil in a non-stick frying pan over medium heat. Cook mushrooms for 4 minutes, then add spinach and stir until wilted. Transfer to a plate.'],['Cook the eggs','Add the remaining oil and pour in the eggs. Gently draw the edges towards the centre, letting uncooked egg flow into the gaps. Reduce the heat.'],['Fold and serve','When the eggs are set, add the vegetables to one half. Fold over and cook for another minute, until no liquid egg remains. Slide onto a plate.']]},
 {id:'salmon',title:'Roasted Salmon & Broccoli',description:'One tray, a squeeze of lemon and dinner is sorted. A little effort goes a long way.',image:5,prep:10,cook:20,kcal:420,protein:36,category:'High protein',equipment:['Oven'],ingredients:[['Salmon',160,'g fillet'],['Broccoli',200,'g'],['Lemon',0.5,''],['Garlic',1,'clove'],['Olive oil',2,'tsp']],steps:[['Heat the oven','Preheat the oven to 200°C (180°C fan). Line a baking tray. Cut broccoli into small, even florets.'],['Start the broccoli','Toss the broccoli with half the oil, minced garlic and a pinch of salt. Spread on the tray and roast for 8 minutes.'],['Add the salmon','Make space for the salmon. Rub with the remaining oil, season and lay lemon slices on top. Roast for 10–12 more minutes, depending on thickness.'],['Check and serve','The salmon should reach 63°C in its thickest part and flake easily. Check the broccoli is tender, then plate everything with the remaining lemon juice.']]},
 {id:'tofu-noodles',title:'Peanut Tofu Noodles',description:'Slippery noodles, golden tofu and a creamy peanut dressing with a little lime zing.',image:6,prep:10,cook:15,kcal:560,protein:28,category:'Vegetarian',equipment:['Stovetop'],ingredients:[['Tofu',150,'g firm'],['Noodles',60,'g dry'],['Carrot',60,'g'],['Peanut butter',1,'tbsp'],['Soy sauce',2,'tsp'],['Lime',0.5,''],['Olive oil',1,'tsp']],steps:[['Make the dressing','Mix peanut butter, soy sauce and lime juice with 1–2 tablespoons of warm water until smooth and pourable.'],['Cook the noodles','Cook noodles according to the packet. Drain and rinse briefly, reserving a splash of cooking water. Shred the carrot into thin ribbons.'],['Brown the tofu','Pat tofu dry and cut into cubes. Heat oil in a non-stick pan over medium-high heat. Cook tofu for 8–10 minutes, turning until golden on several sides.'],['Bring it together','Add carrot, noodles and dressing to the pan. Toss over low heat for 1–2 minutes, adding cooking water as needed to loosen the sauce.']]},
 {id:'bean-stew',title:'Tomato & White Bean Stew',description:'A comforting pot of beans and tomatoes, made for a slice of crusty bread.',image:7,prep:5,cook:20,kcal:340,protein:17,category:'Vegetarian',equipment:['Stovetop'],ingredients:[['White beans',180,'g canned, drained'],['Tomato',200,'g canned'],['Onion',0.5,''],['Garlic',2,'cloves'],['Spinach',50,'g'],['Olive oil',1,'tsp']],steps:[['Soften the onion','Finely chop onion and garlic. Heat oil in a saucepan over medium heat. Cook the onion for 5 minutes until soft, then add garlic for 30 seconds.'],['Build the stew','Add tomatoes and 100 ml water per serving. Bring to a gentle simmer and cook for 8 minutes, stirring occasionally.'],['Add the beans','Rinse and drain the beans, then stir into the sauce. Simmer for 5 minutes until hot. Mash a few beans against the pan to thicken.'],['Stir in the greens','Add spinach and stir for 1–2 minutes until wilted. Season to taste. Serve on its own or with bread (bread adds extra calories).']]},
 {id:'avocado-toast',title:'Avocado & Egg Toast',description:'Crunchy toast, creamy avocado and a warm egg. A small ritual worth making time for.',image:8,prep:5,cook:8,kcal:380,protein:15,category:'Vegetarian',equipment:['Stovetop'],ingredients:[['Bread',2,'small slices'],['Avocado',0.5,''],['Eggs',1,''],['Lemon',0.25,''],['Olive oil',0.5,'tsp']],steps:[['Toast the bread','Warm a dry frying pan over medium heat. Toast the bread for 1–2 minutes on each side until crisp. Set aside.'],['Mash the avocado','Scoop the avocado into a bowl and mash with lemon juice and a pinch of salt and pepper.'],['Cook the egg','Add oil to the pan. Crack in the egg and cook over medium-low heat. Cover for a minute if needed; cook until white and yolk are set.'],['Assemble','Spread avocado over the warm toast. Top with the egg and a little black pepper. Serve straight away.']]},
 {id:'sweet-potato',title:'Loaded Sweet Potato',description:'A fluffy baked sweet potato with chickpeas, tangy yogurt and a scattering of fresh greens.',image:9,prep:5,cook:45,kcal:460,protein:18,category:'Vegetarian',equipment:['Oven'],ingredients:[['Sweet potato',250,'g'],['Chickpeas',100,'g canned, drained'],['Yogurt',60,'g plain'],['Spinach',30,'g'],['Lemon',0.25,''],['Olive oil',1,'tsp']],steps:[['Bake the potato','Heat oven to 220°C (200°C fan). Scrub the sweet potato, prick with a fork and rub with half the oil. Bake on a tray for 40–45 minutes or until a knife slides easily through. Larger potatoes take longer.'],['Roast the chickpeas','Drain and dry the chickpeas. Toss with the remaining oil and a pinch of salt. Add to the tray for the last 15 minutes of cooking.'],['Make the topping','Stir lemon juice into the yogurt. Finely chop the washed spinach.'],['Load it up','Split the potato and fluff the flesh with a fork. Add spinach, hot chickpeas and a spoonful of lemon yogurt.']]},
 {id:'chicken-stirfry',title:'Chicken & Broccoli Stir-fry',description:'Crisp greens and tender chicken in a savoury garlic sauce. A weeknight staple.',image:10,prep:10,cook:20,kcal:510,protein:41,category:'High protein',equipment:['Stovetop'],ingredients:[['Chicken',150,'g'],['Broccoli',150,'g'],['Rice',60,'g dry'],['Garlic',2,'cloves'],['Soy sauce',1,'tbsp'],['Olive oil',1,'tsp']],steps:[['Cook the rice','Rinse rice and cook according to its packet. Meanwhile cut chicken into thin strips and broccoli into small florets. Mince garlic.'],['Brown the chicken','Heat oil in a large frying pan over medium-high heat. Add chicken in a single layer and cook for 5–6 minutes, turning occasionally.'],['Add the vegetables','Add broccoli, garlic and 3 tablespoons water per serving. Cover and cook for 3–4 minutes until the broccoli is tender-crisp.'],['Finish the sauce','Add soy sauce and stir-fry for 1–2 minutes. Check chicken has reached 74°C in the centre. Serve over the hot rice.']]},
 {id:'overnight-oats',title:'Banana Overnight Oats',description:'Five minutes tonight, a creamy breakfast tomorrow. Easy to make and ready when you are.',image:11,prep:5,cook:0,wait:240,kcal:370,protein:18,category:'Vegetarian',equipment:[],ingredients:[['Oats',45,'g'],['Milk',100,'ml'],['Yogurt',100,'g plain'],['Banana',1,'small']],steps:[['Combine the base','In a jar or covered bowl, stir oats, milk and yogurt until evenly combined.'],['Leave overnight','Cover and refrigerate for at least 4 hours or overnight to soften the oats. This waiting time is included in the time filter.'],['Add the banana','Slice the banana just before serving. Stir the oats, adding a splash of milk if you prefer a thinner texture.'],['Enjoy','Top with the banana and eat chilled. Keep the oat mixture refrigerated and eat within 2 days.']]}
];
export const recipes = [...communityRecipes, ...originalRecipes.map(r=>({...r,...originalMedia[r.id]}))];
export const staples = ['Olive oil','Salt','Pepper','Water'];
const asianAreas = new Set(['Chinese','Japanese','Malaysian','Thai','Vietnamese','India','Indian','Korean','Filipino','Indonesian','Singaporean','Taiwanese','Pakistani','Bangladeshi','Sri Lankan','Nepalese','Turkish']);
export const isAsianRecipe = r => asianAreas.has(r.area);
export const ingredients = [...new Set(recipes.flatMap(r=>r.ingredients.map(i=>i[0])))].filter(i=>!staples.includes(i)).sort();
export const totalTime = r => Number.isFinite(r.prep)&&Number.isFinite(r.cook)?r.prep+r.cook+(r.wait||0):Infinity;
export function matchRecipe(r, pantry) {
 const needed=[...new Set(r.ingredients.map(i=>i[0]).filter(i=>!staples.includes(i)))];
 const have=needed.filter(i=>pantry.includes(i));
 return {have:have.length,total:needed.length,missing:needed.filter(i=>!pantry.includes(i)),ratio:needed.length?have.length/needed.length:1};
}
export function filterRecipes(list, f) {
 const q=(f.query||'').trim().toLowerCase();
 return list.filter(r=>{
  const m=matchRecipe(r,f.pantry);
  return (!q||[r.title,r.area||'',...r.ingredients.flatMap(i=>[i[0],i[3]||''])].some(s=>s.toLowerCase().includes(q)))
   &&(!f.pantry.length||m.have>0)&&(!f.onlyHave||m.missing.length===0)
   &&(!f.equipment.length||(Array.isArray(r.equipment)&&r.equipment.every(e=>f.equipment.includes(e))))
   &&(Number(f.time)>=9999||totalTime(r)<=Number(f.time))
   &&(Number(f.calories)>=9999||(Number.isFinite(r.kcal)&&r.kcal<=Number(f.calories)))
   &&(f.category==='All recipes'||(f.category==='Asian'?isAsianRecipe(r):f.category==='Quick & easy'?totalTime(r)<=20:f.category==='High protein'?Number.isFinite(r.protein)&&r.protein>=25:f.category==='Vegetarian'?r.category==='Vegetarian':f.category==='With video'?Boolean(r.videoId):r.category===f.category));
 }).sort((a,b)=>f.sort==='time'?totalTime(a)-totalTime(b):f.sort==='calories'?(a.kcal??Infinity)-(b.kcal??Infinity):matchRecipe(b,f.pantry).ratio-matchRecipe(a,f.pantry).ratio);
}
